import { createFileRoute, Navigate } from '@tanstack/react-router';
import { useEffect, useMemo } from 'react';
import {
  normalizeFunnelSessionStorage,
  readFunnelSession,
} from '@/routes/_authenticated/f/-funnelStorage';

export const Route = createFileRoute('/_authenticated/f/')({
  component: RouteComponent
});

function RouteComponent() {
  const funnelSession = useMemo(() => readFunnelSession(), []);

  useEffect(() => {
    normalizeFunnelSessionStorage();
  }, []);

  if (!funnelSession) {
    return <Navigate to="/f/template" replace />;
  }

  switch (funnelSession.step) {
    case 'prompt':
      return (
        <Navigate
          to="/f/prompt/$productFileId"
          replace
          params={{ productFileId: funnelSession.context.productFileId }}
          search={
            funnelSession.context.fileName
              ? { fileName: funnelSession.context.fileName }
              : undefined
          }
        />
      );
    case 'upload':
      return (
        <Navigate
          to="/f/upload/$productFileId"
          replace
          params={{ productFileId: funnelSession.context.productFileId }}
          search={
            funnelSession.context.fileName
              ? { fileName: funnelSession.context.fileName }
              : undefined
          }
        />
      );
    case 'visual-suggestions':
      return (
        <Navigate
          to="/f/visual-suggestions/$productFileId"
          replace
          params={{ productFileId: funnelSession.context.productFileId }}
          search={
            funnelSession.context.fileName
              ? { fileName: funnelSession.context.fileName }
              : undefined
          }
        />
      );
    case 'settings':
      return (
        <Navigate
          to="/f/settings/$productFileId"
          replace
          params={{ productFileId: funnelSession.context.productFileId }}
          search={
            funnelSession.context.fileName
              ? { fileName: funnelSession.context.fileName }
              : undefined
          }
        />
      );
    case 'output':
      return (
        <Navigate
          to="/f/output/$productFileId"
          replace
          params={{ productFileId: funnelSession.context.productFileId }}
          search={{
            fileName: funnelSession.context.fileName,
            templateFileId: funnelSession.context.templateFileId
          }}
        />
      );
    case 'template':
    default:
      return <Navigate to="/f/template" replace />;
  }
}
